import { faCircleUser } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import React from 'react';
import DatePicker from '../../componnets/datePikers';
import SelectLabels from '../../componnets/selectBox';
import AccordionUsage from '../../componnets/accordion';

const Header = () => {
  return (
    <section className="flex" >
      <div className="flex flex-row items-center w-[20%] justify-center">
        <h1 class="ColorOrange weight900">NESTO</h1>
      </div>

      <div className="flex  w-[60%]">
        <SelectLabels />
        <DatePicker />
        <AccordionUsage />
      </div>

      <div className="">
         <button type="button" class="borderOrange h-[3rem] py-2.5 px-5 me-2 mb-2 text-sm font-medium text-gray-900  rounded-lg  hover:bg-gray-100  focus:z-10 focus:ring-4 focus:ring-gray-100 dark:focus:ring-gray-700 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-600 dark:hover:text-white dark:hover:bg-gray-700">Search</button>
      </div>
    </section>

  );
};

export default Header;
